const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const ukGeom = ee.FeatureCollection("FAO/GAUL/2015/level0")
    .filter(ee.Filter.eq('ADM0_NAME', 'United Kingdom'))
    .geometry();

  const baselineStartYear = 2000;
  const baselineEndYear = 2012;
  const comparisonYear = 2019;
  const startDay = '-02-11';
  const endDay = '-02-25';

  const baselineDateStart = ee.Date(baselineStartYear + startDay);
  const baselineDateEnd = ee.Date(baselineEndYear + endDay);
  const comparisonDateStart = ee.Date(comparisonYear + startDay);
  const comparisonDateEnd = ee.Date(comparisonYear + endDay);

  // 2. Data Acquisition & Processing Function
  const modisLST = 'MODIS/061/MOD11A1';

  const applyScaleAndMask = function(image) {
    const qa = image.select('QC_Day');
    // Bits 0-1: Mandatory QA flags. 00 = LST produced, good quality.
    const qualityMask = qa.bitwiseAnd(3).eq(0);
    const lst = image.select('LST_Day_1km')
      .updateMask(qualityMask)
      .multiply(0.02) // Apply scale factor
      .subtract(273.15); // Convert Kelvin to Celsius
    return lst.rename('LST_C');
  };

  // 3. Baseline Period Analysis
  const baselineCol = ee.ImageCollection(modisLST)
    .filterDate(baselineDateStart, baselineDateEnd)
    .filter(ee.Filter.calendarRange(2, 'month')) // Filter for February
    .filter(ee.Filter.calendarRange(11, 25, 'day_of_month'))
    .filterBounds(ukGeom);

  // Check if baseline collection is empty
  if (baselineCol.size().getInfo() === 0) {
    console.log("No images found for the baseline period (2000-2012).");
    console.log("A"); // C1 is not used for this project, just A/B
    return;
  }

  const baselineImage = baselineCol.map(applyScaleAndMask).mean();

  // 4. Comparison Period Analysis
  const comparisonCol = ee.ImageCollection(modisLST)
    .filterDate(comparisonDateStart, comparisonDateEnd)
    .filterBounds(ukGeom);

  // Check if comparison collection is empty
  if (comparisonCol.size().getInfo() === 0) {
    console.log("No images found for the comparison period (2019).");
    console.log("A"); // C1 is not used for this project, just A/B
    return;
  }

  const comparisonImage = comparisonCol.map(applyScaleAndMask).mean();

  const scale = 3000; // Use a larger scale for a large area to avoid timeout

  // 5. Calculation & Validation
  const baselineStats = baselineImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: ukGeom,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const comparisonStats = comparisonImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: ukGeom,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const baselineTemp = baselineStats['LST_C'];
  const baselinePixels = baselineStats['LST_C_count'];
  const comparisonTemp = comparisonStats['LST_C'];
  const comparisonPixels = comparisonStats['LST_C_count'];

  // Check for C2: No valid pixels after masking
  if (!baselinePixels || baselinePixels === 0) {
    console.log("No valid pixels found for the baseline period after cloud masking.");
    console.log("A"); // C2 is not used for this project, just A/B
    return;
  }
  if (!comparisonPixels || comparisonPixels === 0) {
    console.log("No valid pixels found for the comparison period after cloud masking.");
    console.log("A"); // C2 is not used for this project, just A/B
    return;
  }

  // Check for C3: Calculation Failure
  if (baselineTemp === null || comparisonTemp === null) {
      console.log("Calculation failed: result is null.");
      console.log("A"); // C3 is not used for this project, just A/B
      return;
  }

  // 6. Final Answer
  console.log(`Baseline Avg Temp (2000-2012): ${baselineTemp.toFixed(2)} C`);
  console.log(`Comparison Avg Temp (2019): ${comparisonTemp.toFixed(2)} C`);
  console.log(`Valid Pixel Count (Baseline): ${baselinePixels}`);
  console.log(`Valid Pixel Count (2019): ${comparisonPixels}`);

  if (comparisonTemp > baselineTemp) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
